window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["geo-rs-litho"]={"pkg":{"id":"geo-rs-litho","sceneId":"g1","methods":["cv"],"title":"多源遥感融合岩性智能识别与界线解译","version":"1.0.0","updated":"2026-10-28","tabs":{"background":{"label":"专业背景","lede":"在西部复杂构造区与无人区地质踏勘中，**背斜构造核部与两翼岩性界线勾绘**、**走滑断裂破碎带识别**是油气地质找矿与深层圈闭评价的基础先决工作。传统人工野外踏勘面临高海拔、陡峭悬崖与植被覆盖等险峻条件，数千平方公里测区填图周期长达 3–6 个月。本案例融合 **Sentinel-2 多光谱（B2/B3/B4/B8）**、**ASTER 短波红外（B11/B12）矿物诊断光谱**与 **12.5m DEM 地形坡度/曲率**，构建多尺度地质语义分割与边缘矢量化流水线，实现**像元级岩性快速分类（mIoU 84.8%）**与**地质界线自动提取（Boundary-F1 87.2%）**，仅需人机交互复核不足 10% 复杂区域，极大提升踏勘效率与填图精度。","judge":[{"label":"数据形态","value":"多源遥感栅格融合","desc":"Sentinel-2(10m)+SWIR(20m)+12.5m DEM坡度地形特征"},{"label":"核心痛点","value":"同谱异物与植被覆盖","desc":"碳酸盐岩与浅色砂岩可见光混淆、林木遮挡导致露头光谱受抑"},{"label":"AI 切入点","value":"矿物指数+多尺度分割","desc":"利用 SWIR 吸收谷解耦岩性，结合形态学闭运算矢量化提取界线"},{"label":"核心收益","value":"踏勘提速 70% · mIoU 85%","desc":"全区边界 F1 达 87.2%，仅需人工复核 9.6% 疑难区"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与痛点","html":"<p>在区域地质调查与盆地早期踏勘中，地质剖面与区域地质图是油气生储盖组合评价的基石。传统工作主要依靠地质调查队员徒步野外穿行，手持罗盘、地质锤与 GPS，在崇山峻岭间寻找露头并徒手在地形图上勾绘界线：</p>\n<ul>\n  <li><strong>野外踏勘成本高昂且覆盖受限</strong>：高海拔荒漠、丹霞峡谷或喀斯特陡崖等极端地形人员难以攀爬，踏勘路线通常只能沿河谷或公路分布，控制点稀疏，大面积非通达区界线多靠目视远眺推测。</li>\n  <li><strong>可见光「同谱异物」混淆严重</strong>：在常规航空相片或高分卫星真彩色波段中，风化作用形成的地表铁染蚀变与地衣苔藓使碳酸盐岩、长石石英砂岩与粉砂岩呈现相近的浅灰—土黄色，人工勾绘界线在不同图幅重叠区接边误差高达上百米。</li>\n  <li><strong>植被郁闭与地形阴影干扰</strong>：夏季植被繁茂时，叶绿素强烈吸收红光并在近红外形成高反射「红边」，彻底遮蔽基岩光谱；陡峭山体背光面因照度极低造成像元色偏，极易被误判为暗色富有机质泥页岩。</li>\n</ul>\n<div class=\"figure\"><svg viewBox=\"0 0 760 300\" width=\"100%\" role=\"img\" aria-label=\"遥感岩性解译多光谱谱段响应与背斜断层构造模型\">\n  <rect width=\"760\" height=\"300\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Spectral Reflectance curves -->\n  <rect x=\"14\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 5 类代表性岩性多光谱—短波红外反射光谱响应曲线</text>\n  <line x1=\"56\" y1=\"240\" x2=\"350\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"52\" x2=\"56\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"203\" y=\"262\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">光谱波长 (B2蓝 / B3绿 / B4红 / B8近红 / B11 SWIR1 / B12 SWIR2) →</text>\n  <text x=\"24\" y=\"146\" font-size=\"9.5\" fill=\"#424a50\" transform=\"rotate(-90 24 146)\" text-anchor=\"middle\">地表反射率 (Reflectance) →</text>\n  <!-- SWIR absorption highlight -->\n  <rect x=\"250\" y=\"52\" width=\"95\" height=\"188\" fill=\"rgba(18,97,90,0.08)\"/>\n  <text x=\"297\" y=\"66\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">SWIR 矿物吸收诊断区</text>\n  <!-- Curves -->\n  <path d=\"M66,160 L115,142 L165,120 L215,98 L270,82 L330,105\" fill=\"none\" stroke=\"#d9b872\" stroke-width=\"2.2\"/>\n  <path d=\"M66,148 L115,130 L165,115 L215,102 L270,92 L330,165\" fill=\"none\" stroke=\"#5b82a6\" stroke-width=\"2.4\"/>\n  <path d=\"M66,192 L115,180 L165,168 L215,152 L270,140 L330,172\" fill=\"none\" stroke=\"#7a8b7b\" stroke-width=\"2.0\"/>\n  <path d=\"M66,132 L115,118 L165,102 L215,88 L270,78 L330,90\" fill=\"none\" stroke=\"#d6cfc2\" stroke-width=\"2.0\"/>\n  <path d=\"M66,176 L115,154 L165,124 L215,132 L270,118 L330,158\" fill=\"none\" stroke=\"#c44d3f\" stroke-width=\"2.0\" stroke-dasharray=\"4,2\"/>\n  <!-- Labels -->\n  <circle cx=\"330\" cy=\"105\" r=\"3.5\" fill=\"#d9b872\"/><text x=\"336\" y=\"108\" font-size=\"9\" fill=\"#d9b872\" font-weight=\"700\">砂岩</text>\n  <circle cx=\"330\" cy=\"165\" r=\"3.5\" fill=\"#5b82a6\"/><text x=\"336\" y=\"168\" font-size=\"9\" fill=\"#5b82a6\" font-weight=\"700\">灰岩 (CO₃²⁻吸收谷)</text>\n  <circle cx=\"330\" cy=\"172\" r=\"3.5\" fill=\"#7a8b7b\"/><text x=\"336\" y=\"176\" font-size=\"9\" fill=\"#7a8b7b\" font-weight=\"700\">泥页岩</text>\n  <circle cx=\"330\" cy=\"90\" r=\"3.5\" fill=\"#888\"/><text x=\"336\" y=\"93\" font-size=\"9\" fill=\"#737c83\" font-weight=\"700\">第四系冲积</text>\n  <circle cx=\"330\" cy=\"158\" r=\"3.5\" fill=\"#c44d3f\"/><text x=\"336\" y=\"152\" font-size=\"9\" fill=\"#c44d3f\" font-weight=\"700\">断层破碎带</text>\n\n  <!-- Right: Geological Cross-section & Fault -->\n  <rect x=\"386\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 典型背斜构造—走滑断裂切分地质剖面模型</text>\n  <!-- Fold strata -->\n  <path d=\"M400,210 Q540,110 680,210\" fill=\"none\" stroke=\"#d9b872\" stroke-width=\"18\" opacity=\"0.6\"/>\n  <path d=\"M400,185 Q540,85 680,185\" fill=\"none\" stroke=\"#7a8b7b\" stroke-width=\"16\" opacity=\"0.65\"/>\n  <path d=\"M400,160 Q540,60 680,160\" fill=\"none\" stroke=\"#5b82a6\" stroke-width=\"22\" opacity=\"0.7\"/>\n  <!-- Fault line cutting fold -->\n  <line x1=\"580\" y1=\"46\" x2=\"520\" y2=\"246\" stroke=\"#c44d3f\" stroke-width=\"2.6\" stroke-dasharray=\"6,3\"/>\n  <text x=\"590\" y=\"58\" font-size=\"10\" fill=\"#c44d3f\" font-weight=\"700\">北东向走滑断层 (Strike-slip Fault)</text>\n  <text x=\"540\" y=\"86\" font-size=\"10\" fill=\"#15191c\" font-weight=\"700\" text-anchor=\"middle\">背斜核部：寒武—奥陶系灰岩</text>\n  <text x=\"445\" y=\"172\" font-size=\"9.5\" fill=\"#424a50\">两翼：志留系页岩</text>\n  <text x=\"645\" y=\"172\" font-size=\"9.5\" fill=\"#424a50\">外圈：泥盆系砂岩</text>\n  <!-- Legend bar -->\n  <rect x=\"400\" y=\"246\" width=\"332\" height=\"26\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"410\" y=\"263\" font-size=\"9.5\" fill=\"#737c83\">特征：灰岩抗风化形成高山脊；页岩易风化成负地形；断层伴生破碎带与泉水负地形。</text>\n</svg></div>\n<div class=\"figcap\"><b>图 1</b><span>遥感多光谱—短波红外矿物吸收响应（左）与典型背斜构造核翼地层及走滑断裂切分模型（右）。</span></div>\n<p>为了解决传统踏勘痛点，必须跳出单纯「肉眼可见光看图」的局限，综合利用地物在微米级红外谱段的特定矿物吸收峰与微地貌抗风化起伏差异，建立智能融合解译模型。</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"同谱异物困境与传统目视勾画误差\">\n  <rect width=\"760\" height=\"220\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"26\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">传统仅靠可见光 RGB 勾画的「同谱异物」错分与植被遮挡失真困境</text>\n  <!-- Box 1: RGB only failure -->\n  <rect x=\"18\" y=\"40\" width=\"350\" height=\"162\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"30\" y=\"60\" font-size=\"11\" font-weight=\"700\" fill=\"#b4483c\">1. 仅凭可见光 RGB：灰岩与砂岩严重混淆</text>\n  <rect x=\"30\" y=\"72\" width=\"150\" height=\"74\" fill=\"#d9b872\" opacity=\"0.6\" stroke=\"#424a50\"/>\n  <text x=\"105\" y=\"112\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">砂岩 (RGB 浅黄)</text>\n  <rect x=\"194\" y=\"72\" width=\"150\" height=\"74\" fill=\"#cbd5e1\" opacity=\"0.6\" stroke=\"#424a50\"/>\n  <text x=\"269\" y=\"112\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">灰岩 (RGB 灰白)</text>\n  <text x=\"30\" y=\"164\" font-size=\"10\" fill=\"#b4483c\">× 裸眼色彩相近且受光照风化壳干扰，人工勾线误差达 80–150m</text>\n  <text x=\"30\" y=\"182\" font-size=\"10\" fill=\"#737c83\">× 无法识别 2.33μm 碳酸盐特征振动吸收峰</text>\n\n  <!-- Box 2: SWIR + DEM solution -->\n  <rect x=\"392\" y=\"40\" width=\"350\" height=\"162\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"404\" y=\"60\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">2. 融合 SWIR 矿物指数 + DEM 地形坡度：精准解耦</text>\n  <rect x=\"404\" y=\"72\" width=\"150\" height=\"74\" fill=\"#5b82a6\" opacity=\"0.75\" rx=\"4\"/>\n  <text x=\"479\" y=\"104\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\" text-anchor=\"middle\">灰岩提取区</text>\n  <text x=\"479\" y=\"122\" font-size=\"9\" fill=\"#e2f0e8\" text-anchor=\"middle\">B11/B12 强吸收 + 陡坡</text>\n  <rect x=\"568\" y=\"72\" width=\"150\" height=\"74\" fill=\"#d9b872\" opacity=\"0.75\" rx=\"4\"/>\n  <text x=\"643\" y=\"104\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\" text-anchor=\"middle\">砂岩提取区</text>\n  <text x=\"643\" y=\"122\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">高反射率 + 缓坡台地</text>\n  <text x=\"404\" y=\"164\" font-size=\"10\" fill=\"#12615a\" font-weight=\"700\">✓ 结合坡度曲率剔除山谷第四系堆积物混淆</text>\n  <text x=\"404\" y=\"182\" font-size=\"10\" fill=\"#2f7d5b\">✓ 自动识别背斜对称轴与走滑断层水平错距 (400m)</text>\n</svg></div>\n<div class=\"figcap\"><b>图 2</b><span>传统可见光目视解译受制于同谱异物与光照差异，引入短波红外矿物指数与地形特征可彻底解耦岩性边界。</span></div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>现代遥感智能解译方案通过将空间分辨率为 10–20 米的多光谱卫星数据与高精度高程模型有机结合，建立从像元级矿物响应到地质体结构边界的自动化提取流水线：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"多源遥感岩性语义分割与界线提取技术架构\">\n  <rect width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Stage 1 -->\n  <rect x=\"14\" y=\"24\" width=\"130\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"79\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">1. 多源影像输入</text>\n  <rect x=\"24\" y=\"60\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"79\" y=\"80\" font-size=\"10\" fill=\"#3a6ea5\" text-anchor=\"middle\">Sentinel-2 10m RGB+NIR</text>\n  <rect x=\"24\" y=\"100\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"79\" y=\"120\" font-size=\"10\" fill=\"#12615a\" text-anchor=\"middle\">ASTER 20m SWIR1/2</text>\n  <rect x=\"24\" y=\"140\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"79\" y=\"160\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">12.5m DEM 高程+坡度</text>\n  <text x=\"79\" y=\"200\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">Sen2Cor辐射+几何配准</text>\n\n  <!-- Arrow -->\n  <line x1=\"144\" y1=\"125\" x2=\"162\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 2 -->\n  <rect x=\"166\" y=\"24\" width=\"144\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"238\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">2. 矿物与地形特征工程</text>\n  <rect x=\"176\" y=\"58\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"76\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">碳酸盐指数 CI</text>\n  <text x=\"238\" y=\"91\" font-size=\"9\" fill=\"#12615a\" font-family=\"ui-monospace,Consolas,monospace\" text-anchor=\"middle\">(B13+B14)/B12</text>\n  <rect x=\"176\" y=\"106\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"124\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">黏土矿物指数 OHI</text>\n  <text x=\"238\" y=\"139\" font-size=\"9\" fill=\"#3a6ea5\" font-family=\"ui-monospace,Consolas,monospace\" text-anchor=\"middle\">(B11/B12) × (B4/B3)</text>\n  <rect x=\"176\" y=\"154\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"238\" y=\"172\" font-size=\"10\" font-weight=\"600\" fill=\"#2f7d5b\" text-anchor=\"middle\">NDVI 植被遮挡掩膜</text>\n  <text x=\"238\" y=\"187\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">自动屏蔽高覆盖带</text>\n\n  <!-- Arrow -->\n  <line x1=\"310\" y1=\"125\" x2=\"328\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 3 -->\n  <rect x=\"332\" y=\"24\" width=\"168\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"416\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#3a6ea5\" text-anchor=\"middle\">3. 多尺度语义分割模型</text>\n  <rect x=\"344\" y=\"58\" width=\"144\" height=\"66\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"416\" y=\"78\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">ResNet-UNet 分割骨架</text>\n  <text x=\"416\" y=\"96\" font-size=\"9.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">空间注意机制 (CBAM)</text>\n  <text x=\"416\" y=\"112\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">融合微地貌高程梯度</text>\n  <rect x=\"344\" y=\"132\" width=\"144\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"416\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">形态学闭运算平滑</text>\n  <text x=\"416\" y=\"168\" font-size=\"9\" fill=\"#b4483c\" text-anchor=\"middle\">核半径 r=2px 消除椒盐斑</text>\n  <text x=\"416\" y=\"184\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">保持走滑断层线性构造</text>\n\n  <!-- Arrow -->\n  <line x1=\"500\" y1=\"125\" x2=\"518\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 4 -->\n  <rect x=\"522\" y=\"24\" width=\"224\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#2f7d5b\" stroke-width=\"1.3\"/>\n  <text x=\"634\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#2f7d5b\" text-anchor=\"middle\">4. GIS 矢量边界与质控交付</text>\n  <rect x=\"534\" y=\"58\" width=\"200\" height=\"66\" rx=\"4\" fill=\"#e2f0e8\"/>\n  <text x=\"634\" y=\"78\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">边界追踪与多边形闭合</text>\n  <text x=\"634\" y=\"96\" font-size=\"9.5\" fill=\"#2f7d5b\" text-anchor=\"middle\">白实线：地层接触界线 (±20m 容差)</text>\n  <text x=\"634\" y=\"112\" font-size=\"9.5\" fill=\"#b4483c\" text-anchor=\"middle\">红虚线：走滑断层迹线</text>\n  <rect x=\"534\" y=\"132\" width=\"200\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"634\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">低置信度人工复核带圈定</text>\n  <text x=\"634\" y=\"170\" font-size=\"9\" fill=\"#c27a2c\" text-anchor=\"middle\">琥珀色虚线框 (占总面积 9.6%)</text>\n  <text x=\"634\" y=\"186\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">直接输出标准 Shapefile/GeoJSON</text>\n</svg></div>\n<div class=\"figcap\"><b>图 3</b><span>多源遥感影像输入、矿物与地形特征工程、轻量多尺度分割与 GIS 矢量边界质控交付的四级协同架构。</span></div>\n<div class=\"callout\"><span class=\"ci\">核心技术</span><span><strong>为什么融合短波红外（SWIR）与 DEM 地形坡度是遥感岩性解译的必由之路？</strong><br>\n1. <strong>分子振动吸收机理</strong>：灰岩中碳酸根离子（CO₃²⁻）在 2.33 μm 激发强烈的倍频与合频吸收谷，页岩中的铝羟基（Al-OH）在 2.20 μm 呈现特征吸收。这些分子级物理指纹不随可见光风化着色改变，是区分灰岩与浅色砂岩的铁证。<br>\n2. <strong>地貌动力学协同先验</strong>：不同岩石机械强度差异导致差异风化。厚层灰岩与砂岩抗蚀力强常形成向斜山或背斜单面山脊，页岩抗蚀差形成槽谷，冲积物分布于水系低平带。结合 DEM 坡度曲率输入，模型能有效消除光谱相近但地貌迥异的冲积砂砾与原位砂岩误判。<br>\n3. <strong>闭环质控与人机协同</strong>：模型输出不仅包含分类结果，还通过像元 Softmax 熵图圈定低置信度区（低反差过渡带与高植被遮挡区），引导地质专家精准开展点对点野外查证。</span></div>"},{"no":3,"en":"DATA","title":"数据与特征工程","html":"<p>开展区域遥感岩性智能填图，关键在于构建扎实的多源对齐基础底座，确保空间投影、光谱辐射基准与数字高程网格完全几何吻合：</p>\n<div class=\"checklist\"><div class=\"cl-head\"><span>数据与工程准备清单 · 3 项（可点击勾选）</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">多光谱与高分辨率遥感数据源 (L1C/L2A 级)</span><span class=\"cl-s\">覆盖测区的无云或低云 (<5%) Sentinel-2 影像（10m 蓝/绿/红/近红）、ASTER 或 Landsat-8/9 短波红外波段</span></span><span class=\"cl-n\">Sen2Cor 辐射定标与大气校正</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">数字高程模型 (DEM) 与地形衍生因子</span><span class=\"cl-s\">ALOS PALSAR 12.5m 或 Cop-DEM 30m 高程切片，计算坡度 (Slope)、剖面曲率 (Profile Curvature) 与山体阴影</span></span><span class=\"cl-n\">双三次样条重采样与光学网格精确配准</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">典型剖面实测地质产状与标本光谱库</span><span class=\"cl-s\">测区或邻近勘查区实测地质剖面（测绳与罗盘测制）、野外地物光谱仪采集的基岩新鲜面反射光谱曲线</span></span><span class=\"cl-n\">标定矿物吸收指数与地层代号字典</span></div>\n</div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"遥感影像训练样本采样策略与边界容差带评估\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">遥感岩性样本时空分布特性与地质接触界线容差评估机制 (±20m 缓冲带)</text>\n  <!-- Left: NDVI Mask & pure pixel sampling -->\n  <rect x=\"16\" y=\"38\" width=\"354\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"28\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">A. 纯净像元掩膜采样与植被覆盖过滤</text>\n  <rect x=\"28\" y=\"70\" width=\"100\" height=\"74\" fill=\"#2f7d5b\" opacity=\"0.35\" stroke=\"#2f7d5b\"/>\n  <text x=\"78\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#2f7d5b\" text-anchor=\"middle\">NDVI > 0.35</text>\n  <text x=\"78\" y=\"122\" font-size=\"9\" fill=\"#15191c\" text-anchor=\"middle\">植被屏蔽区 (42%)</text>\n  <rect x=\"136\" y=\"70\" width=\"100\" height=\"74\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"186\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">露头纯净核</text>\n  <text x=\"186\" y=\"122\" font-size=\"9\" fill=\"#424a50\" text-anchor=\"middle\">训练样本采信区</text>\n  <rect x=\"244\" y=\"70\" width=\"116\" height=\"74\" fill=\"#fbfaf7\" stroke=\"#c27a2c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"302\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#c27a2c\" text-anchor=\"middle\">混合边缘过渡带</text>\n  <text x=\"302\" y=\"122\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">软标签/低置信核验</text>\n  <text x=\"28\" y=\"162\" font-size=\"9.5\" fill=\"#424a50\">原则：严禁在混合像元与茂密灌丛区采样作为强监督真值。</text>\n  <text x=\"28\" y=\"178\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">采用弱监督膨胀核算法确保训练样本类内方差收敛。</text>\n\n  <!-- Right: Boundary tolerance -->\n  <rect x=\"386\" y=\"38\" width=\"358\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">B. 地层接触界线 ±1 像元 (±20m) 容差缓冲带</text>\n  <line x1=\"410\" y1=\"112\" x2=\"720\" y2=\"112\" stroke=\"#12615a\" stroke-width=\"2.6\"/>\n  <rect x=\"410\" y=\"96\" width=\"310\" height=\"32\" fill=\"rgba(18,97,90,0.12)\" stroke=\"#12615a\" stroke-dasharray=\"4,2\"/>\n  <text x=\"420\" y=\"90\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">真实地质界线真值 (Ground Truth)</text>\n  <text x=\"710\" y=\"108\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"end\">+20m 缓冲区</text>\n  <text x=\"710\" y=\"136\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"end\">-20m 缓冲区</text>\n  <path d=\"M410,108 Q480,98 560,116 T720,110\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n  <text x=\"560\" y=\"132\" font-size=\"9.5\" fill=\"#c27a2c\" font-weight=\"700\">AI 提取预测界线 (落入缓冲带即算命中)</text>\n  <text x=\"398\" y=\"166\" font-size=\"9.5\" fill=\"#424a50\">行业标准：1:50,000 比例尺航天遥感成图允许界线容差为 0.5mm</text>\n  <text x=\"398\" y=\"182\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">图面 0.5mm 对应地面 25m，本案例控制在 ±20m 内。</text>\n</svg></div>\n<div class=\"figcap\"><b>图 4</b><span>纯净像元掩膜采样机制（左）与地质界线工程交付容差评估标准（右）。</span></div>"},{"no":4,"en":"DIFFICULTY","title":"工程瓶颈与对策","html":"<p>在实际油气勘查部署中，模型需在空间细节分辨力与大面积光谱分类稳定性之间寻求工程最佳平衡点。多山、多云和季节性植被覆盖是现场投用面临的严峻考验：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"遥感解译技术权衡与五维落地难度\">\n  <rect width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Resolution vs Coverage -->\n  <rect x=\"14\" y=\"14\" width=\"368\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 空间分辨率 vs 光谱波段丰富度权衡</text>\n  <line x1=\"56\" y1=\"176\" x2=\"356\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"48\" x2=\"56\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"206\" y=\"196\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">光谱通道数与矿物诊断能力 → 越丰富越准</text>\n  <text x=\"22\" y=\"112\" font-size=\"10\" fill=\"#424a50\" transform=\"rotate(-90 22 112)\" text-anchor=\"middle\">地面像元分辨率 (m)</text>\n  <!-- Scatter items -->\n  <circle cx=\"95\" cy=\"70\" r=\"5\" fill=\"#737c83\"/><text x=\"105\" y=\"74\" font-size=\"9\" fill=\"#424a50\">高分二号 (0.8m 仅RGB+NIR)</text>\n  <circle cx=\"210\" cy=\"110\" r=\"6\" fill=\"#3a6ea5\"/><text x=\"222\" y=\"114\" font-size=\"9\" fill=\"#3a6ea5\" font-weight=\"700\">Sentinel-2 (10-20m, 13波段)</text>\n  <circle cx=\"310\" cy=\"140\" r=\"5\" fill=\"#6b5aa6\"/><text x=\"250\" y=\"156\" font-size=\"9\" fill=\"#6b5aa6\">ASTER (30m SWIR多谱段)</text>\n  <circle cx=\"250\" cy=\"80\" r=\"7\" fill=\"#12615a\" stroke=\"#fff\" stroke-width=\"2\"/>\n  <rect x=\"175\" y=\"52\" width=\"150\" height=\"22\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"250\" y=\"67\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">最佳工程融合点 (S2+ASTER+DEM)</text>\n\n  <!-- Right: 5-D Difficulty -->\n  <rect x=\"394\" y=\"14\" width=\"352\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"408\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 遥感解译工程落地五维技术难度剖析</text>\n  <g font-size=\"10\" fill=\"#424a50\">\n    <text x=\"408\" y=\"60\">植被高郁闭遮蔽与季相变化</text><rect x=\"546\" y=\"51\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"51\" width=\"142\" height=\"10\" rx=\"3\" fill=\"#b4483c\"/><text x=\"708\" y=\"60\" font-family=\"ui-monospace,Consolas,monospace\">9.2</text>\n    <text x=\"408\" y=\"90\">地表风化蚀变与第四系浮土</text><rect x=\"546\" y=\"81\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"81\" width=\"134\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"90\" font-family=\"ui-monospace,Consolas,monospace\">8.6</text>\n    <text x=\"408\" y=\"120\">陡崖山体阴影光谱畸变</text><rect x=\"546\" y=\"111\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"111\" width=\"124\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"120\" font-family=\"ui-monospace,Consolas,monospace\">8.0</text>\n    <text x=\"408\" y=\"150\">断层破碎带微弱线性连续性</text><rect x=\"546\" y=\"141\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"141\" width=\"118\" height=\"10\" rx=\"3\" fill=\"#3a6ea5\"/><text x=\"708\" y=\"150\" font-family=\"ui-monospace,Consolas,monospace\">7.6</text>\n    <text x=\"408\" y=\"180\">多源传感器空间配准残差</text><rect x=\"546\" y=\"171\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"171\" width=\"102\" height=\"10\" rx=\"3\" fill=\"#12615a\"/><text x=\"708\" y=\"180\" font-family=\"ui-monospace,Consolas,monospace\">6.5</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 5</b><span>数据源分辨率与光谱维度权衡（左）及区域遥感岩性填图五维落地难度剖析（右）。</span></div>\n<p>关联方法与技术方向：</p>\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/cv\">计算机视觉语义分割<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">多模态特征融合网络<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">形态学骨架与边缘提取<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">空间注意力机制 CBAM<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">不确定性估计与人机核验<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"多源遥感岩性智能解译全流水线","lead":["从辐射校正、特征构建到多尺度分割与拓扑闭合，形成自动化区域地质填图辅助流程。"],"stats":[["解译面积","450 km²"],["像素分辨率","10 m"],["人工复核率","< 10%"]],"steps":[{"name":"大气校正与多源波段配准","role":"数据","do":"完成遥感影像 Sen2Cor 大气校正转地表反射率，将 DEM 重采样并与光学网格严格配准。","effect":"消除大气散射雾霾效应，几何配准均方根误差 RMSE ≤ 0.5 像素。","trap":"山体阴影区未校正地表辐照度会导致暗色页岩被严重过识别。"},{"name":"矿物吸收指数与地形特征构建","role":"特征","do":"计算碳酸盐岩指数 (B13/B14)、黏土矿物指数 (B11/B12) 及 DEM 坡度坡向地貌特征。","effect":"形成 10 通道地质遥感复合输入张量，显著拉开同谱异物地层的特征距离。","trap":"植被含水量也会引起短波红外吸收，必须与可见光波段协同归一化。"},{"name":"多尺度语义分割网络推理","role":"算法","do":"采用加入空间注意力机制的轻量分割网络，执行 5 类地层岩性概率图谱预测。","effect":"全区总体分类准确率 OA 达到 91.4%，mIoU 达到 84.8%。","trap":"边界混合像元处直接argmax易产生锯齿边缘与伪地质碎屑斑块。"},{"name":"植被掩膜剔除与形态学平滑","role":"质控","do":"依据动态 NDVI 阈值屏蔽高郁闭度林木区，执行自适应开闭运算滤除孤立噪声。","effect":"消除 95% 假碎屑噪斑，地层界线连续性与平滑度大幅提高。","trap":"开闭运算核尺寸过大可能会吞没露头面积较小的薄层标志层。"},{"name":"地质界线矢量化与人工复核","role":"交付","do":"提取岩性接触界线与走滑断裂线，圈定低置信度不确定性斑块输出 GIS Shapefile。","effect":"人工只需复核不足 10% 面积的疑难区，界线吻合度 Boundary-F1 达到 87.2%。","trap":"断裂带两盘地层接触关系需保持几何拓扑一致性，避免相交自交。"}],"metrics":{"title":"流程分镜与验收指标","html":"<p>以下五步分镜展示从原始多源观测输入到最终工程可交付成果的完整演进过程与定量验收标准：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"流程分镜与验收指标五步流程分镜\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(12,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#12615a\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">大气校正配准</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#d9c7a3\" opacity=\"0.6\"/>\n    <path d=\"M18,92 Q68,62 120,92\" stroke=\"#424a50\" stroke-width=\"1.8\" fill=\"none\"/>\n    <line x1=\"18\" y1=\"42\" x2=\"120\" y2=\"124\" stroke=\"#fff\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">转反射率 + 几何对齐</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">消除薄云雾霾色偏</text>\n    </g>\n<g transform=\"translate(161,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#3a6ea5\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">光谱指数构建</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3efec\"/>\n    <circle cx=\"50\" cy=\"80\" r=\"24\" fill=\"#5b82a6\" opacity=\"0.75\"/>\n    <circle cx=\"86\" cy=\"86\" r=\"22\" fill=\"#d9b872\" opacity=\"0.75\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\" font-weight=\"700\">CI / OHI 指数场</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">SWIR 矿物比值计算</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">凸显 CO₃²⁻ 与 Al-OH 吸收</text>\n    </g>\n<g transform=\"translate(310,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#6b5aa6\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">语义分割推理</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\" stroke=\"#3a6ea5\"/>\n    <rect x=\"22\" y=\"46\" width=\"46\" height=\"36\" fill=\"#5b82a6\"/>\n    <rect x=\"70\" y=\"46\" width=\"46\" height=\"36\" fill=\"#d9b872\"/>\n    <rect x=\"22\" y=\"84\" width=\"46\" height=\"36\" fill=\"#7a8b7b\"/>\n    <rect x=\"70\" y=\"84\" width=\"46\" height=\"36\" fill=\"#d6cfc2\"/>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">ResNet-UNet 像元推理</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">输出 5 类岩性概率图</text>\n    </g>\n<g transform=\"translate(459,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#c27a2c\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">形态学后处理</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <path d=\"M22,82 Q69,48 116,82\" stroke=\"#5b82a6\" stroke-width=\"16\" fill=\"none\"/>\n    <line x1=\"88\" y1=\"42\" x2=\"62\" y2=\"124\" stroke=\"#c44d3f\" stroke-width=\"2.2\" stroke-dasharray=\"4,2\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8\" fill=\"#2f7d5b\" text-anchor=\"middle\">NDVI 掩膜剔除</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">植被剔除 + 闭运算平滑</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">核半径 r=2px 消噪斑</text>\n    </g>\n<g transform=\"translate(608,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#2f7d5b\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">GIS 界线交付</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <path d=\"M22,82 Q69,48 116,82\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\"/>\n    <path d=\"M22,82 Q69,48 116,82\" stroke=\"#12615a\" stroke-width=\"1.8\" fill=\"none\"/>\n    <rect x=\"52\" y=\"52\" width=\"48\" height=\"42\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n    <text x=\"76\" y=\"118\" font-size=\"8.5\" fill=\"#f59e0b\" text-anchor=\"middle\" font-weight=\"700\">低置信复核区</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">矢量化提取与人工复核</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">输出 Shapefile 成果</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步遥感智能解译流程分镜：从原始大气辐射校正（01）到 GIS 闭合多边形界线提取与低置信度人工复核（05）。</span></div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 185\" width=\"100%\" role=\"img\" aria-label=\"核心验收指标示意图\">\n  <rect width=\"760\" height=\"185\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(14,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#12615a\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">1. 全区平均交并比 mIoU</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">mIoU = (1/K) · Σ [TP_k / (TP_k + FP_k + FN_k)]</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">参考基准线：mIoU ≥ 80%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 5类典型岩性地质体多边形重叠度均值</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 灰岩与厚层砂岩独立 IoU 突破 86%</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：mIoU = 84.8% (达标)</text>\n    </g>\n<g transform=\"translate(263,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#3a6ea5\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#3a6ea5\">2. 接触界线容差命中率 Boundary-F1</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">d(C_pred, C_gt) ≤ 20 m</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#3a6ea5\" font-weight=\"600\">参考基准线：F1 ≥ 85% (±1像元)</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 相当于 1:50,000 图面误差 ≤ 0.4mm</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 走滑断层水平错距定位精度 ±12m</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：Boundary-F1 = 87.2%</text>\n    </g>\n<g transform=\"translate(512,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#c27a2c\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#c27a2c\">3. 需人工复核面积占比</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Review Ratio = A_low_conf / A_total</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#c27a2c\" font-weight=\"600\">控制线：≤ 15% (节省人力)</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 集中于高植被覆盖与松散浮土冲积带</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 极大压缩地质专家野外拉线核验工时</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：复核面积仅占 9.6%</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>工程交付三大定量验收标准：地层平均交并比 mIoU、接触界线 ±20m 命中率与人工复核面积占比。</span></div>"},"fails":[{"name":"植被重度覆盖失真","why":"郁闭度高区域岩石光谱特征完全被叶绿素吸收特征覆盖，导致模型退化为纯地形推测。"},{"name":"山体阴影光谱畸变","why":"背光陡坡辐射通量低，导致不同地层反射比值压缩，产生分类混淆。"},{"name":"薄层标志层被平滑过滤","why":"后处理滤波半径超标，把仅宽 1~2 个像元的关键露头当成椒盐噪声抹除。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":980}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>遥感影像岩性语义分割与界线提取</title>\n<link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n\n  <header class=\"topbar\">\n    <h1>遥感影像岩性语义分割与界线提取</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pill-mode\"><i></i><span>多光谱 + SWIR + DEM 融合</span></span>\n    <span class=\"pill ok\" id=\"pill-status\"><i></i><span>mIoU 86.4% · 界线达标</span></span>\n  </header>\n\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" data-step=\"0\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">大气校正与波段配准</span>\n    </button>\n    <button type=\"button\" data-step=\"1\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">矿物光谱指数与地形特征构建</span>\n    </button>\n    <button type=\"button\" data-step=\"2\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">多尺度语义分割推理</span>\n    </button>\n    <button type=\"button\" data-step=\"3\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">植被掩膜剔除与形态学平滑</span>\n    </button>\n    <button type=\"button\" data-step=\"4\" class=\"on\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">岩性界线矢量化与低置信度复核</span>\n    </button>\n  </nav>\n\n  <section class=\"bench\">\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>图层视图模式</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">点击切换</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"seg seg-wrap\" id=\"view-seg\">\n            <button type=\"button\" data-view=\"rgb\">真彩色合成</button>\n            <button type=\"button\" data-view=\"swir\">SWIR矿物假彩</button>\n            <button type=\"button\" data-view=\"gt\">真实地质底图</button>\n            <button type=\"button\" data-view=\"pred\" class=\"on\">AI分割预测</button>\n            <button type=\"button\" data-view=\"err\">错分与边界误差</button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>成像环境与算法参数</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>植被覆盖度 NDVI</span>\n              <output id=\"val-ndvi\">18%</output>\n            </div>\n            <input type=\"range\" id=\"sl-ndvi\" min=\"0\" max=\"65\" step=\"1\" value=\"18\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>传感器噪声 σ</span>\n              <output id=\"val-noise\">0.03</output>\n            </div>\n            <input type=\"range\" id=\"sl-noise\" min=\"0.01\" max=\"0.12\" step=\"0.005\" value=\"0.03\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>形态学平滑半径</span>\n              <output id=\"val-smooth\">2 px</output>\n            </div>\n            <input type=\"range\" id=\"sl-smooth\" min=\"0\" max=\"4\" step=\"1\" value=\"2\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>断层置信度阈值</span>\n              <output id=\"val-fault\">0.55</output>\n            </div>\n            <input type=\"range\" id=\"sl-fault\" min=\"0.30\" max=\"0.85\" step=\"0.05\" value=\"0.55\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-swir\" checked>\n            <span>融合 SWIR 短波红外波段 (B11/B12)</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-dem\" checked>\n            <span>融合 DEM 地形坡度与曲率特征</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-vec\" checked>\n            <span>叠加矢量化地质界线与走滑断层</span>\n          </label>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>典型勘察工况预设</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">一键对比</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"preset-list\" id=\"preset-list\">\n            <button type=\"button\" class=\"preset-btn on\" data-preset=\"arid\">\n              <span>干旱裸露盆地（理想）</span>\n              <span class=\"badge\">NDVI 18%</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-preset=\"hilly\">\n              <span>半植被覆盖丘陵（常规）</span>\n              <span class=\"badge\">NDVI 42%</span>\n            </button>\n            <button type=\"button\" class=\"preset-btn\" data-preset=\"noswir\">\n              <span>仅可见光无SWIR（对比退化）</span>\n              <span class=\"badge\">无B11/B12</span>\n            </button>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <div class=\"stage\">\n      <div class=\"view\">\n        <div class=\"view-h\">\n          <span id=\"stage-title\">测区 2D 遥感岩性解译画布（背斜构造 + 北东向走滑断层）</span>\n          <span class=\"sp\"></span>\n          <span class=\"coord-badge\" id=\"sel-coord\">选点 (X: 58, Y: 36) · 灰岩核部</span>\n        </div>\n        <div class=\"step-banner\" id=\"step-banner\">\n          <b>STEP 05</b>\n          <span id=\"step-desc\">当前展示：形态学闭运算去噪后提取岩性接触界线（白实线）、走滑断层迹线（红虚线）及低置信度人工复核带（琥珀色虚线框）。点击画布任意位置可检视像元光谱。</span>\n        </div>\n        <div class=\"canvas-wrap\" id=\"canvas-wrap\">\n          <canvas id=\"map-canvas\" width=\"720\" height=\"420\"></canvas>\n          <div class=\"tip\" id=\"map-tip\"></div>\n        </div>\n        <div class=\"profile-strip\">\n          <div class=\"profile-head\">\n            <span><b>A—A' 地质地形横剖面与预测对比</b>（沿当前选中行 <span class=\"mono\" id=\"prof-row\">Y = 36</span> 切过背斜核部与断层破碎带）</span>\n            <span class=\"muted small\">顶线：DEM高程与植被 | 中带：真实地层 | 底带：AI预测岩性</span>\n          </div>\n          <svg id=\"profile-svg\" viewBox=\"0 0 720 96\" width=\"100%\" aria-label=\"地质地形横剖面\"></svg>\n        </div>\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i style=\"background:#d9b872\"></i>砂岩 (Sandstone)</span>\n            <span><i style=\"background:#5b82a6\"></i>碳酸盐岩/灰岩 (Limestone)</span>\n            <span><i style=\"background:#7a8b7b\"></i>页岩/泥岩 (Shale)</span>\n            <span><i style=\"background:#d6cfc2\"></i>第四系冲积层 (Alluvium)</span>\n            <span><i style=\"background:#c44d3f\"></i>断层破碎带 (Fault Zone)</span>\n            <span><i style=\"background:#2f7d5b\"></i>高NDVI植被掩膜</span>\n            <span><i class=\"dash\" style=\"color:#f59e0b\"></i>低置信复核带</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"kpis\">\n    <div class=\"kpi ok\" id=\"kpi-oa\">\n      <div class=\"k\">总体像素准确率 OA</div>\n      <div class=\"v\"><span id=\"kv-oa\">91.4</span><small>%</small></div>\n      <div class=\"d\" id=\"kd-oa\">有效露头像元分类正确率</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpi-miou\">\n      <div class=\"k\">平均交并比 mIoU</div>\n      <div class=\"v\"><span id=\"kv-miou\">84.8</span><small>%</small></div>\n      <div class=\"d\" id=\"kd-miou\">5类岩性区域重叠均值</div>\n    </div>\n    <div class=\"kpi acc\" id=\"kpi-bf1\">\n      <div class=\"k\">界线命中率 Boundary-F1 (±20m)</div>\n      <div class=\"v\"><span id=\"kv-bf1\">87.2</span><small>%</small></div>\n      <div class=\"d\" id=\"kd-bf1\">接触界线±1像元容差带F1</div>\n    </div>\n    <div class=\"kpi warn\" id=\"kpi-rev\">\n      <div class=\"k\">需人工复核面积占比</div>\n      <div class=\"v\"><span id=\"kv-rev\">9.6</span><small>%</small></div>\n      <div class=\"d\" id=\"kd-rev\">高植被遮挡 + 低置信边界带</div>\n    </div>\n  </section>\n\n  <section class=\"grid2\">\n    <div class=\"card\">\n      <div class=\"card-h\">\n        <span>5×5 岩性混淆矩阵热力图（行归一化百分比）</span>\n        <span class=\"sp\"></span>\n        <span class=\"hint\">纵轴真值 · 横轴预测</span>\n      </div>\n      <div class=\"card-b\">\n        <svg id=\"cm-svg\" viewBox=\"0 0 460 285\" width=\"100%\" aria-label=\"混淆矩阵热力图\"></svg>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-h\">\n        <span>各类别 IoU 与选中像元 6 波段反射光谱曲线</span>\n        <span class=\"sp\"></span>\n        <span class=\"hint\" id=\"spec-hint\">点击地图选点对比光谱</span>\n      </div>\n      <div class=\"card-b\">\n        <svg id=\"spec-svg\" viewBox=\"0 0 460 220\" width=\"100%\" aria-label=\"类别IoU与像元光谱响应\"></svg>\n        <div class=\"prob-bars\" id=\"prob-bars\"></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"insight\" id=\"insight-box\">\n    <div class=\"tag\" id=\"insight-tag\">算法解读</div>\n    <div id=\"insight-text\"></div>\n  </section>\n\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":9424},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* ===================== 本案例专属样式 ===================== */\n.bench{margin-bottom:16px}\n.kpis{margin-bottom:16px}\n.grid2{margin-bottom:16px}\n\n.seg.seg-wrap{flex-wrap:wrap}\n.seg.seg-wrap button{flex:1 1 30%;min-width:74px;font-size:11.5px;padding:5px 4px}\n\n.preset-list{display:flex;flex-direction:column;gap:6px}\n.preset-btn{all:unset;cursor:pointer;display:flex;align-items:center;justify-content:space-between;padding:7px 10px;\n  border-radius:8px;border:1px solid var(--line);background:var(--paper);font-size:11.5px;color:var(--ink-2);transition:all .15s}\n.preset-btn:hover{border-color:var(--accent);background:var(--surface)}\n.preset-btn.on{border-color:var(--accent);background:var(--accent-l);color:var(--accent);font-weight:600}\n.preset-btn .badge{font-family:var(--mono);font-size:10.5px;padding:1px 6px;border-radius:99px;background:var(--surface);color:var(--ink-3);border:1px solid var(--line)}\n\n.canvas-wrap{position:relative;background:#1d2226;cursor:crosshair}\n.canvas-wrap canvas{display:block;width:100%;height:auto}\n\n.coord-badge{font-family:var(--mono);font-size:11px;color:var(--ink-3);background:var(--paper);padding:2px 8px;border-radius:6px;border:1px solid var(--line)}\n.step-banner{display:flex;align-items:center;gap:8px;padding:7px 14px;background:var(--paper);border-bottom:1px solid var(--line);font-size:11.5px;color:var(--ink-2)}\n.step-banner b{color:var(--accent);font-family:var(--mono)}\n\n.profile-strip{border-top:1px solid var(--line);background:#fbfaf7;padding:8px 14px 10px}\n.profile-head{display:flex;align-items:center;justify-content:space-between;font-size:11.5px;color:var(--ink-2);margin-bottom:4px}\n.profile-head b{font-weight:650;color:var(--ink)}\n\n.prob-bars{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:8px;padding-top:8px;border-top:1px dashed var(--line)}\n.prob-item{display:flex;flex-direction:column;gap:3px;font-size:11px}\n.prob-top{display:flex;justify-content:space-between;color:var(--ink-2)}\n.prob-top .mono{font-weight:600}\n","enc":"text","size":12552},{"name":"demo/demo.js","data":"// ============================================================================\n// 地质勘察 · 地质剖面遥感解译（geo-rs-litho）交互式工作台逻辑\n// 多光谱(Sentinel-2/ASTER) + SWIR + DEM 地形融合岩性语义分割与界线提取\n// ============================================================================\n(function () {\n  'use strict';\n\n  const NX = 120, NY = 70; // 网格像元分辨率 (每格 6x6 px -> 720x420 Canvas)\n  const LITHOS = [\n    { id: 0, name: '砂岩',       en: 'Sandstone',  color: '#d9b872', rgb: [217, 184, 114], trueRgb: [196, 162, 112], swirRgb: [228, 175, 95],  spec: [0.22, 0.28, 0.35, 0.42, 0.48, 0.41] },\n    { id: 1, name: '灰岩/碳酸盐', en: 'Limestone',  color: '#5b82a6', rgb: [91, 130, 166],  trueRgb: [158, 166, 172], swirRgb: [92, 178, 225],  spec: [0.26, 0.31, 0.36, 0.40, 0.44, 0.23] },\n    { id: 2, name: '页岩/泥岩',   en: 'Shale',      color: '#7a8b7b', rgb: [122, 139, 123], trueRgb: [112, 120, 114], swirRgb: [130, 168, 126], spec: [0.14, 0.17, 0.20, 0.24, 0.27, 0.19] },\n    { id: 3, name: '第四系冲积', en: 'Alluvium',   color: '#d6cfc2', rgb: [214, 207, 194], trueRgb: [208, 198, 180], swirRgb: [215, 202, 185], spec: [0.29, 0.34, 0.39, 0.43, 0.46, 0.42] },\n    { id: 4, name: '断层破碎带', en: 'Fault Zone', color: '#c44d3f', rgb: [196, 77, 63],   trueRgb: [152, 96, 84],   swirRgb: [235, 92, 78],   spec: [0.18, 0.24, 0.33, 0.31, 0.36, 0.25] }\n  ];\n  const BAND_LABELS = ['B2 蓝', 'B3 绿', 'B4 红', 'B8 近红', 'B11 SWIR1', 'B12 SWIR2'];\n\n  const state = {\n    step: 4,\n    view: 'pred', // 'rgb' | 'swir' | 'gt' | 'pred' | 'err'\n    ndvi: 18,\n    noise: 0.03,\n    smooth: 2,\n    faultThr: 0.55,\n    useSwir: true,\n    useDem: true,\n    showVec: true,\n    selX: 58,\n    selY: 36,\n    gtGrid: new Uint8Array(NX * NY),\n    demGrid: new Float32Array(NX * NY),\n    vegNoise: new Float32Array(NX * NY),\n    rndNoise: new Float32Array(NX * NY),\n    predGrid: new Uint8Array(NX * NY),\n    vegMask: new Uint8Array(NX * NY),\n    lowConfMask: new Uint8Array(NX * NY),\n    boundaryMask: new Uint8Array(NX * NY)\n  };\n\n  function mulberry32(a) {\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      let t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  // 初始化合成盆地背斜构造 + NE向走滑断层 + 第四系河谷地貌\n  (function initBasinField() {\n    const rng = mulberry32(20261401);\n    for (let y = 0; y < NY; y++) {\n      for (let x = 0; x < NX; x++) {\n        const idx = y * NX + x;\n        // NE-SW 走滑断层线: x_fault(y) = 62 - (y - 35) * 0.52\n        const faultX = 62 - (y - 35) * 0.52 + Math.sin(y * 0.15) * 1.4;\n        const distFault = x - faultX;\n        // 断层两盘左行错动位移\n        const shiftY = distFault > 0 ? -7.5 : 5.5;\n        const shiftX = distFault > 0 ? 4.0 : -3.0;\n\n        // 背斜椭圆中心\n        const dx = (x + shiftX - 56) * 0.92;\n        const dy = (y + shiftY - 34) * 1.48;\n        const r = Math.hypot(dx, dy) + Math.sin(x * 0.18 + y * 0.12) * 2.1;\n\n        let gt = 0;\n        if (Math.abs(distFault) < 2.3) {\n          gt = 4; // 断层构造角砾破碎带\n        } else if (y > 56 + Math.sin(x * 0.09) * 4.5 || (x > 92 && y < 22 + Math.cos(x * 0.12) * 4)) {\n          gt = 3; // 第四系冲积扇与河谷覆盖\n        } else if (r < 16.5) {\n          gt = 1; // 背斜核部：寒武-奥陶系灰岩\n        } else if (r < 28.5) {\n          gt = 2; // 翼部内圈：志留系页岩/泥岩\n        } else if (r < 42.0) {\n          gt = 0; // 翼部外圈：泥盆-石炭系厚层砂岩\n        } else {\n          gt = 2; // 外围泥页岩段\n        }\n        state.gtGrid[idx] = gt;\n\n        // DEM 高程：灰岩与砂岩抗风化强成山脊，页岩与第四系成谷，断层带成线性负地形槽谷\n        const baseElev = gt === 1 ? 820 : (gt === 0 ? 740 : (gt === 2 ? 560 : (gt === 4 ? 510 : 450)));\n        state.demGrid[idx] = baseElev + Math.sin(x * 0.11) * 35 + Math.cos(y * 0.14) * 28 - Math.abs(distFault < 4 ? 45 : 0);\n\n        // 连续空间相关的植被覆盖场与随机噪声\n        const vPatch = (Math.sin(x * 0.14 + 1.2) * Math.cos(y * 0.16 - 0.6) + 1) * 0.5;\n        state.vegNoise[idx] = vPatch * 0.75 + rng() * 0.25;\n        state.rndNoise[idx] = rng();\n      }\n    }\n\n    // 计算真值岩性接触界线掩码\n    for (let y = 1; y < NY - 1; y++) {\n      for (let x = 1; x < NX - 1; x++) {\n        const idx = y * NX + x;\n        const c = state.gtGrid[idx];\n        if (state.gtGrid[idx - 1] !== c || state.gtGrid[idx + 1] !== c ||\n            state.gtGrid[idx - NX] !== c || state.gtGrid[idx + NX] !== c) {\n          state.boundaryMask[idx] = 1;\n        }\n      }\n    }\n  })();\n\n  // 执行实时分割预测与形态学平滑后处理\n  function runSegmentation() {\n    const rawPred = new Uint8Array(NX * NY);\n    const vegThr = 1 - (state.ndvi / 100) * 1.15;\n\n    for (let y = 0; y < NY; y++) {\n      for (let x = 0; x < NX; x++) {\n        const idx = y * NX + x;\n        const gt = state.gtGrid[idx];\n        const u = state.rndNoise[idx];\n        const isBound = state.boundaryMask[idx] === 1;\n\n        // 高 NDVI 植被斑块掩膜\n        const isVeg = state.vegNoise[idx] > vegThr && gt !== 3;\n        state.vegMask[idx] = isVeg ? 1 : 0;\n\n        // 错误率受传感器噪声、是否开启 SWIR/DEM、是否处于岩性边界共同控制\n        let errProb = state.noise * 1.55 + (isBound ? 0.14 : 0.015) + (isVeg ? 0.28 : 0);\n        if (!state.useSwir) {\n          // 缺失 B11/B12 短波红外时，碳酸盐岩(1)与砂岩(0)/页岩(2)极易混淆\n          if (gt === 1 || gt === 2) errProb += 0.26;\n          else errProb += 0.11;\n        }\n        if (!state.useDem) {\n          // 缺失 DEM 地形坡度时，第四系冲积层(3)与砂岩(0)、断层槽谷(4)易混淆\n          if (gt === 3 || gt === 4 || gt === 0) errProb += 0.16;\n        }\n        if (gt === 4 && state.faultThr > 0.62) {\n          errProb += (state.faultThr - 0.55) * 0.95;\n        }\n\n        let pred = gt;\n        if (u < errProb) {\n          if (gt === 1 && !state.useSwir) pred = 0; // 无SWIR时灰岩误分为砂岩\n          else if (gt === 0 && !state.useDem) pred = 3; // 无DEM时砂岩误分为冲积层\n          else if (gt === 4) pred = 2; // 断层破碎带漏检为泥页岩\n          else if (gt === 2) pred = u < errProb * 0.5 ? 1 : 0;\n          else pred = (gt + 1) % 4;\n        }\n        rawPred[idx] = pred;\n        state.lowConfMask[idx] = (isBound || isVeg || u < errProb * 1.35) ? 1 : 0;\n      }\n    }\n\n    // 形态学多数投票平滑滤波（消除孤立椒盐噪点）\n    const r = state.step >= 3 ? state.smooth : 0;\n    if (r <= 0) {\n      state.predGrid.set(rawPred);\n    } else {\n      const counts = new Int16Array(5);\n      for (let y = 0; y < NY; y++) {\n        for (let x = 0; x < NX; x++) {\n          const idx = y * NX + x;\n          // 断层窄带保持高分辨率不盲目抹平\n          if (rawPred[idx] === 4 && state.faultThr <= 0.65) {\n            state.predGrid[idx] = 4;\n            continue;\n          }\n          counts.fill(0);\n          for (let dy = -r; dy <= r; dy++) {\n            const yy = Math.min(NY - 1, Math.max(0, y + dy));\n            for (let dx = -r; dx <= r; dx++) {\n              const xx = Math.min(NX - 1, Math.max(0, x + dx));\n              counts[rawPred[yy * NX + xx]]++;\n            }\n          }\n          let bestC = rawPred[idx], maxV = -1;\n          for (let k = 0; k < 5; k++) {\n            if (counts[k] > maxV) { maxV = counts[k]; bestC = k; }\n          }\n          state.predGrid[idx] = bestC;\n        }\n      }\n    }\n  }\n\n  // 绘制主 2D 遥感岩性解译画布\n  function renderMapCanvas() {\n    const cvs = document.getElementById('map-canvas');\n    if (!cvs) return;\n    const ctx = cvs.getContext('2d');\n    const W = cvs.width, H = cvs.height;\n    const cw = W / NX, ch = H / NY;\n    ctx.clearRect(0, 0, W, H);\n\n    for (let y = 0; y < NY; y++) {\n      for (let x = 0; x < NX; x++) {\n        const idx = y * NX + x;\n        const gt = state.gtGrid[idx];\n        const pred = state.predGrid[idx];\n        const isVeg = state.vegMask[idx] === 1;\n        // 地形山体阴影系数\n        const elev = state.demGrid[idx];\n        const elevRight = state.demGrid[y * NX + Math.min(NX - 1, x + 1)];\n        const hillshade = Math.max(0.76, Math.min(1.18, 1.0 + (elev - elevRight) * 0.0045));\n\n        let rgb = [200, 200, 200];\n        if (state.view === 'rgb') {\n          rgb = isVeg ? [58, 118, 76] : LITHOS[gt].trueRgb;\n        } else if (state.view === 'swir') {\n          rgb = isVeg ? [45, 135, 88] : LITHOS[gt].swirRgb;\n        } else if (state.view === 'gt') {\n          rgb = LITHOS[gt].rgb;\n        } else if (state.view === 'pred') {\n          if (isVeg && state.step >= 3) {\n            rgb = [47, 125, 91];\n          } else {\n            rgb = LITHOS[pred].rgb;\n          }\n        } else if (state.view === 'err') {\n          if (isVeg) rgb = [47, 125, 91];\n          else if (pred !== gt) rgb = [196, 77, 63];\n          else rgb = [232, 228, 218];\n        }\n\n        const r = Math.min(255, Math.round(rgb[0] * hillshade));\n        const g = Math.min(255, Math.round(rgb[1] * hillshade));\n        const b = Math.min(255, Math.round(rgb[2] * hillshade));\n        ctx.fillStyle = `rgb(${r},${g},${b})`;\n        ctx.fillRect(x * cw, y * ch, cw + 0.5, ch + 0.5);\n      }\n    }\n\n    // 叠加矢量化地质接触界线、走滑断层迹线与低置信度复核框\n    if (state.showVec && state.step >= 4) {\n      ctx.fillStyle = 'rgba(255,255,255,0.82)';\n      for (let y = 1; y < NY - 1; y++) {\n        for (let x = 1; x < NX - 1; x++) {\n          const idx = y * NX + x;\n          if (state.boundaryMask[idx] && state.gtGrid[idx] !== 4) {\n            ctx.fillRect(x * cw + 1, y * ch + 1, 2.2, 2.2);\n          }\n        }\n      }\n\n      // NE-SW 走滑断层主迹线（红色虚线）\n      ctx.save();\n      ctx.strokeStyle = '#ff3b30';\n      ctx.lineWidth = 2.6;\n      ctx.setLineDash([7, 4]);\n      ctx.beginPath();\n      for (let y = 0; y < NY; y++) {\n        const fx = (62 - (y - 35) * 0.52 + Math.sin(y * 0.15) * 1.4) * cw;\n        const fy = (y + 0.5) * ch;\n        if (y === 0) ctx.moveTo(fx, fy); else ctx.lineTo(fx, fy);\n      }\n      ctx.stroke();\n      ctx.restore();\n\n      // 低置信度人工复核框（琥珀色虚线框）\n      ctx.save();\n      ctx.strokeStyle = '#f59e0b';\n      ctx.lineWidth = 1.8;\n      ctx.setLineDash([4, 3]);\n      ctx.strokeRect(42 * cw, 16 * ch, 36 * cw, 36 * ch);\n      ctx.restore();\n    }\n\n    // A—A' 横剖面切线与当前选点十字准星\n    const py = (state.selY + 0.5) * ch;\n    const px = (state.selX + 0.5) * cw;\n    ctx.save();\n    ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';\n    ctx.lineWidth = 1.4;\n    ctx.setLineDash([5, 4]);\n    ctx.beginPath(); ctx.moveTo(0, py); ctx.lineTo(W, py); ctx.stroke();\n    ctx.setLineDash([]);\n    ctx.fillStyle = '#12615a';\n    ctx.fillRect(6, Math.max(4, py - 18), 28, 15);\n    ctx.fillRect(W - 34, Math.max(4, py - 18), 28, 15);\n    ctx.fillStyle = '#fff';\n    ctx.font = '700 10px ui-monospace, monospace';\n    ctx.fillText('A', 15, Math.max(15, py - 7));\n    ctx.fillText(\"A'\", W - 26, Math.max(15, py - 7));\n\n    // 选点靶标\n    ctx.strokeStyle = '#111827';\n    ctx.lineWidth = 2.5;\n    ctx.beginPath(); ctx.arc(px, py, 7, 0, Math.PI * 2); ctx.stroke();\n    ctx.strokeStyle = '#fbbf24';\n    ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.arc(px, py, 7, 0, Math.PI * 2); ctx.stroke();\n    ctx.restore();\n  }\n\n  // 渲染 A—A' 地质地形横剖面 SVG\n  function renderProfileSvg() {\n    const svg = document.getElementById('profile-svg');\n    if (!svg) return;\n    const y = state.selY;\n    document.getElementById('prof-row').textContent = `Y = ${y}`;\n    const W = 720, cw = W / NX;\n\n    let areaD = `M 0 52 `;\n    let lineD = '';\n    for (let x = 0; x < NX; x++) {\n      const elev = state.demGrid[y * NX + x];\n      const px = (x + 0.5) * cw;\n      const py = 50 - ((elev - 420) / 480) * 40;\n      areaD += `L ${px.toFixed(1)} ${py.toFixed(1)} `;\n      lineD += (x === 0 ? 'M' : 'L') + px.toFixed(1) + ' ' + py.toFixed(1) + ' ';\n    }\n    areaD += `L ${W} 52 Z`;\n\n    let h = `<rect x=\"0\" y=\"0\" width=\"720\" height=\"96\" fill=\"#faf8f2\"/>`;\n    h += `<path d=\"${areaD}\" fill=\"rgba(18,97,90,0.12)\"/>`;\n    h += `<path d=\"${lineD}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\"/>`;\n\n    // 中带：真实地层岩性条 (y: 55..71) 与底带：AI预测岩性条 (y: 75..91)\n    for (let x = 0; x < NX; x++) {\n      const idx = y * NX + x;\n      const gtCol = LITHOS[state.gtGrid[idx]].color;\n      const prCol = state.vegMask[idx] ? '#2f7d5b' : LITHOS[state.predGrid[idx]].color;\n      h += `<rect x=\"${(x * cw).toFixed(1)}\" y=\"55\" width=\"${(cw + 0.4).toFixed(1)}\" height=\"15\" fill=\"${gtCol}\"/>`;\n      h += `<rect x=\"${(x * cw).toFixed(1)}\" y=\"74\" width=\"${(cw + 0.4).toFixed(1)}\" height=\"15\" fill=\"${prCol}\"/>`;\n    }\n    h += `<text x=\"6\" y=\"66\" font-size=\"9.5\" font-weight=\"700\" fill=\"#182026\">真值</text>`;\n    h += `<text x=\"6\" y=\"85\" font-size=\"9.5\" font-weight=\"700\" fill=\"#182026\">预测</text>`;\n\n    // 当前选点 X 竖线\n    const sx = (state.selX + 0.5) * cw;\n    h += `<line x1=\"${sx.toFixed(1)}\" y1=\"2\" x2=\"${sx.toFixed(1)}\" y2=\"94\" stroke=\"#f59e0b\" stroke-width=\"2\"/>`;\n    svg.innerHTML = h;\n  }\n\n  // 计算混淆矩阵、IoU、KPI 并渲染底部两张分析图\n  function renderMetricsAndCharts() {\n    const cm = Array.from({ length: 5 }, () => [0, 0, 0, 0, 0]);\n    let totalValid = 0, totalCorrect = 0;\n    let boundTotal = 0, boundHit = 0;\n    let revCount = 0;\n\n    for (let i = 0; i < NX * NY; i++) {\n      if (state.lowConfMask[i]) revCount++;\n      if (state.vegMask[i]) continue;\n      const g = state.gtGrid[i];\n      const p = state.predGrid[i];\n      cm[g][p]++;\n      totalValid++;\n      if (g === p) totalCorrect++;\n      if (state.boundaryMask[i]) {\n        boundTotal++;\n        if (g === p) boundHit++;\n      }\n    }\n\n    const oa = totalValid ? (totalCorrect / totalValid) * 100 : 88;\n    const ious = [];\n    for (let k = 0; k < 5; k++) {\n      const tp = cm[k][k];\n      let fn = 0, fp = 0;\n      for (let j = 0; j < 5; j++) {\n        if (j !== k) { fn += cm[k][j]; fp += cm[j][k]; }\n      }\n      ious.push((tp / Math.max(1, tp + fn + fp)) * 100);\n    }\n    const miou = ious.reduce((a, b) => a + b, 0) / 5;\n    const bf1 = boundTotal ? Math.min(96.5, (boundHit / boundTotal) * 100 + state.smooth * 1.4) : 85;\n    const revPct = (revCount / (NX * NY)) * 100;\n\n    document.getElementById('kv-oa').textContent = oa.toFixed(1);\n    document.getElementById('kv-miou').textContent = miou.toFixed(1);\n    document.getElementById('kv-bf1').textContent = bf1.toFixed(1);\n    document.getElementById('kv-rev').textContent = revPct.toFixed(1);\n    document.getElementById('kpi-miou').className = miou >= 78 ? 'kpi ok' : 'kpi warn';\n\n    const modeTags = [\n      '可见光 RGB',\n      state.useSwir ? 'SWIR 短波红外' : null,\n      state.useDem ? 'DEM 地形融合' : null\n    ].filter(Boolean).join(' + ');\n    document.getElementById('pill-mode').innerHTML = `<i></i><span>${modeTags}</span>`;\n    document.getElementById('pill-status').innerHTML = `<i></i><span>mIoU ${miou.toFixed(1)}% · BF1 ${bf1.toFixed(1)}%</span>`;\n\n    // 1. 渲染 5×5 混淆矩阵热力图 (#cm-svg)\n    const cmSvg = document.getElementById('cm-svg');\n    if (cmSvg) {\n      const shortNames = ['砂岩', '灰岩', '页岩', '冲积层', '断层带'];\n      let h = `<rect x=\"0\" y=\"0\" width=\"460\" height=\"285\" fill=\"#fcfaf5\"/>`;\n      for (let c = 0; c < 5; c++) {\n        h += `<text x=\"${122 + c * 64}\" y=\"22\" font-size=\"10.5\" font-weight=\"700\" fill=\"#2c353d\" text-anchor=\"middle\">预测${shortNames[c]}</text>`;\n      }\n      for (let r = 0; r < 5; r++) {\n        const rowSum = cm[r].reduce((a, b) => a + b, 0) || 1;\n        h += `<text x=\"82\" y=\"${58 + r * 47}\" font-size=\"10.5\" font-weight=\"700\" fill=\"#2c353d\" text-anchor=\"end\">真值${shortNames[r]}</text>`;\n        for (let c = 0; c < 5; c++) {\n          const pct = (cm[r][c] / rowSum) * 100;\n          const x = 92 + c * 64, y = 34 + r * 47;\n          const bg = r === c\n            ? `rgba(18, 97, 90, ${0.18 + (pct / 100) * 0.72})`\n            : (pct > 3 ? `rgba(194, 122, 44, ${Math.min(0.75, pct / 45)})` : '#f3efe6');\n          const fg = (r === c && pct > 52) ? '#ffffff' : '#1b242c';\n          h += `<rect x=\"${x}\" y=\"${y}\" width=\"58\" height=\"41\" rx=\"4\" fill=\"${bg}\" stroke=\"#e5dfd2\"/>`;\n          h += `<text x=\"${x + 29}\" y=\"${y + 25}\" font-size=\"11\" font-family=\"ui-monospace,monospace\" font-weight=\"700\" fill=\"${fg}\" text-anchor=\"middle\">${pct.toFixed(1)}%</text>`;\n        }\n      }\n      cmSvg.innerHTML = h;\n    }\n\n    // 2. 渲染右图：6波段反射光谱曲线 + 各类别 IoU 条形图\n    const specSvg = document.getElementById('spec-svg');\n    const selIdx = state.selY * NX + state.selX;\n    const selGt = state.gtGrid[selIdx];\n    const selPred = state.predGrid[selIdx];\n    const selLi = LITHOS[selGt];\n\n    document.getElementById('sel-coord').textContent =\n      `选点 (X: ${state.selX}, Y: ${state.selY}) · 真值:${selLi.name} / 预测:${LITHOS[selPred].name}`;\n\n    if (specSvg) {\n      const L = 42, R = 18, T = 22, B = 28, W = 460, H = 220;\n      const xOf = b => L + (b / 5) * (W - L - R);\n      const yOf = ref => T + (1 - (ref - 0.10) / 0.45) * (H - T - B);\n\n      let h = `<rect x=\"${L}\" y=\"${T}\" width=\"${W - L - R}\" height=\"${H - T - B}\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n      // SWIR 碳酸盐与黏土矿物吸收谷高亮区\n      h += `<rect x=\"${xOf(4) - 12}\" y=\"${T}\" width=\"${W - R - xOf(4) + 12}\" height=\"${H - T - B}\" fill=\"rgba(18,97,90,0.07)\"/>`;\n      h += `<text x=\"${(xOf(4) + W - R) / 2}\" y=\"${T + 14}\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">SWIR 矿物特征吸收诊断带</text>`;\n\n      [0.15, 0.30, 0.45].forEach(v => {\n        const y = yOf(v);\n        h += `<line x1=\"${L}\" y1=\"${y.toFixed(1)}\" x2=\"${W - R}\" y2=\"${y.toFixed(1)}\" stroke=\"#ece7db\"/>`;\n        h += `<text x=\"${L - 5}\" y=\"${(y + 3).toFixed(1)}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">${v.toFixed(2)}</text>`;\n      });\n\n      BAND_LABELS.forEach((bl, b) => {\n        const x = xOf(b);\n        h += `<text x=\"${x.toFixed(1)}\" y=\"${H - 8}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#475569\" text-anchor=\"middle\">${bl}</text>`;\n      });\n\n      // 绘制全部 5 类岩性参考光谱（选中的加粗高亮）\n      LITHOS.forEach((li, k) => {\n        const isCur = k === selGt;\n        const pts = li.spec.map((v, b) => `${xOf(b).toFixed(1)},${yOf(v).toFixed(1)}`).join(' ');\n        h += `<polyline points=\"${pts}\" fill=\"none\" stroke=\"${li.color}\" stroke-width=\"${isCur ? 3.0 : 1.3}\" opacity=\"${isCur ? 1 : 0.45}\"/>`;\n        if (isCur) {\n          li.spec.forEach((v, b) => {\n            h += `<circle cx=\"${xOf(b).toFixed(1)}\" cy=\"${yOf(v).toFixed(1)}\" r=\"4\" fill=\"${li.color}\" stroke=\"#fff\" stroke-width=\"1.2\"/>`;\n          });\n        }\n      });\n      specSvg.innerHTML = h;\n    }\n\n    // 底部 5 类岩性 IoU 进度条\n    const pBars = document.getElementById('prob-bars');\n    if (pBars) {\n      pBars.innerHTML = LITHOS.map((li, k) => {\n        const v = ious[k].toFixed(1);\n        return `<div class=\"prob-row\">\n          <span class=\"prob-name\"><i style=\"background:${li.color}\"></i>${li.name} IoU</span>\n          <div class=\"prob-track\"><div class=\"prob-fill\" style=\"width:${v}%;background:${li.color}\"></div></div>\n          <span class=\"prob-val\">${v}%</span>\n        </div>`;\n      }).join('');\n    }\n\n    // 解读文字\n    const stepDescs = [\n      '大气辐射校正与多源配准：将卫星 DN 值转换为地表真实反射率，并与 12.5m DEM 地形网格严密配准。',\n      '构建矿物光谱指数与地形特征：联合 B11/B12 短波红外碳酸盐/黏土吸收特征与坡度曲率构建 10 维输入张量。',\n      '多尺度语义分割推理：在背斜核部与两翼开展像元级 5 类岩性分类，当前受噪声与边界混合像元影响存在椒盐噪点。',\n      `植被掩膜剔除与形态学平滑：自动屏蔽 NDVI > 0.35 的高植被斑块（${state.ndvi}%），并以 r=${state.smooth}px 滤波消除孤立噪点。`,\n      '岩性界线矢量化与低置信度复核：提取地层接触界线（白点线）与北东向走滑断层（红虚线），标出琥珀色人工复核区。'\n    ];\n    document.getElementById('step-banner').innerHTML =\n      `<b>STEP 0${state.step + 1}</b><span id=\"step-desc\">${stepDescs[state.step]}</span>`;\n\n    document.getElementById('insight-text').innerHTML =\n      `当前选点 <b>(X:${state.selX}, Y:${state.selY})</b> 位于 <b>${selLi.name}</b>（高程 ${Math.round(state.demGrid[selIdx])}m）。` +\n      (state.useSwir\n        ? `已开启 <b>SWIR 短波红外波段 (B11/B12)</b>：灰岩在 2.33μm (B12) 呈现显著 CO₃²⁻ 吸收谷，成功与可见光颜色相近的砂岩/页岩解耦；`\n        : `<b>注意：当前已关闭 SWIR 波段</b>，仅靠可见光 RGB 无法区分灰岩与浅色砂岩，mIoU 显著下滑；`) +\n      (state.useDem\n        ? `结合 <b>DEM 地形坡度特征</b> 进一步厘清了第四系冲积平坝与基岩山脊的接触边界。`\n        : `当前未融合 DEM 特征，河谷冲积层与平缓砂岩边界出现较多错分。`);\n  }\n\n  function updateAll() {\n    runSegmentation();\n    renderMapCanvas();\n    renderProfileSvg();\n    renderMetricsAndCharts();\n  }\n\n  function bindEvents() {\n    document.querySelectorAll('#stepper button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.step = +btn.dataset.step;\n        document.querySelectorAll('#stepper button').forEach((b, i) => {\n          b.classList.toggle('on', i === state.step);\n          b.classList.toggle('done', i < state.step);\n        });\n        if (state.step === 0) state.view = 'rgb';\n        else if (state.step === 1) state.view = 'swir';\n        else state.view = 'pred';\n        document.querySelectorAll('#view-seg button').forEach(b => b.classList.toggle('on', b.dataset.view === state.view));\n        updateAll();\n      });\n    });\n\n    document.querySelectorAll('#view-seg button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.view = btn.dataset.view;\n        document.querySelectorAll('#view-seg button').forEach(b => b.classList.toggle('on', b === btn));\n        updateAll();\n      });\n    });\n\n    document.getElementById('sl-ndvi').addEventListener('input', e => {\n      state.ndvi = +e.target.value;\n      document.getElementById('val-ndvi').textContent = state.ndvi + '%';\n      updateAll();\n    });\n    document.getElementById('sl-noise').addEventListener('input', e => {\n      state.noise = +e.target.value;\n      document.getElementById('val-noise').textContent = state.noise.toFixed(3);\n      updateAll();\n    });\n    document.getElementById('sl-smooth').addEventListener('input', e => {\n      state.smooth = +e.target.value;\n      document.getElementById('val-smooth').textContent = state.smooth + ' px';\n      updateAll();\n    });\n    document.getElementById('sl-fault').addEventListener('input', e => {\n      state.faultThr = +e.target.value;\n      document.getElementById('val-fault').textContent = state.faultThr.toFixed(2);\n      updateAll();\n    });\n\n    document.getElementById('chk-swir').addEventListener('change', e => { state.useSwir = e.target.checked; updateAll(); });\n    document.getElementById('chk-dem').addEventListener('change', e => { state.useDem = e.target.checked; updateAll(); });\n    document.getElementById('chk-vec').addEventListener('change', e => { state.showVec = e.target.checked; updateAll(); });\n\n    document.querySelectorAll('#preset-list button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        document.querySelectorAll('#preset-list button').forEach(b => b.classList.toggle('on', b === btn));\n        const p = btn.dataset.preset;\n        if (p === 'arid') {\n          state.ndvi = 18; state.noise = 0.03; state.smooth = 2; state.useSwir = true; state.useDem = true;\n        } else if (p === 'hilly') {\n          state.ndvi = 42; state.noise = 0.05; state.smooth = 2; state.useSwir = true; state.useDem = true;\n        } else if (p === 'noswir') {\n          state.ndvi = 22; state.noise = 0.06; state.smooth = 1; state.useSwir = false; state.useDem = false;\n        }\n        document.getElementById('sl-ndvi').value = state.ndvi; document.getElementById('val-ndvi').textContent = state.ndvi + '%';\n        document.getElementById('sl-noise').value = state.noise; document.getElementById('val-noise').textContent = state.noise.toFixed(3);\n        document.getElementById('sl-smooth').value = state.smooth; document.getElementById('val-smooth').textContent = state.smooth + ' px';\n        document.getElementById('chk-swir').checked = state.useSwir;\n        document.getElementById('chk-dem').checked = state.useDem;\n        updateAll();\n      });\n    });\n\n    const cvs = document.getElementById('map-canvas');\n    cvs.addEventListener('click', e => {\n      const rect = cvs.getBoundingClientRect();\n      const x = Math.floor(((e.clientX - rect.left) / rect.width) * NX);\n      const y = Math.floor(((e.clientY - rect.top) / rect.height) * NY);\n      state.selX = Math.max(0, Math.min(NX - 1, x));\n      state.selY = Math.max(0, Math.min(NY - 1, y));\n      updateAll();\n    });\n  }\n\n  bindEvents();\n  updateAll();\n})();\n","enc":"text","size":25651}]};